fi
SESSION_SECRET_VALUE=$(openssl rand -hex 32 2>/dev/null || head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')
DEMO_CODE_VALUE=$(_existing DEMO_ACCESS_CODE || openssl rand -hex 8 2>/dev/null || head -c 8 /dev/urandom | od -An -tx1 | tr -d ' \n')
write_env ENVIRONMENT "production"
write_env SESSION_SECRET "$SESSION_SECRET_VALUE"
write_env DEMO_ACCESS_CODE "$DEMO_CODE_VALUE"
note "ENVIRONMENT=production is what lets visitors dial THEIR OWN phones:"
note "outside production the gateway refuses any number not on DIAL_ALLOWLIST."
ask DEMO_USER_EMAIL "Demo account email (needn't be a real mailbox) [demo@becca.live]:"
DEMO_USER_EMAIL=${DEMO_USER_EMAIL:-demo@becca.live}
write_env DEMO_USER_EMAIL "$DEMO_USER_EMAIL"
say ""
say "Pick your two Render service names now — they become the hostnames."
