note "COOKIE_DOMAIN is deliberately EMPTY: onrender.com is on the browsers'"
note "Public Suffix List, so cookies cannot span the two services. Sessions"
note "are host-only — which is why the QR code must use the app host."
write_env PUBLIC_WEBHOOK_BASE "https://${APP_SERVICE}.onrender.com"
note "Webhooks target the app service — it's the one we keep awake, and the"
note "one that settles test-call billing when Telnyx reports the call ended."
write_env TELNYX_MODE "real"
write_env MAX_CALL_MINUTES "5"
note "MAX_CALL_MINUTES=5 caps every call and shrinks the per-call wallet hold"
note "to \$1.50 at the default \$0.30/min — more concurrent visitors per \$."
write_env DIAL_ALLOWLIST ""
write_env ASSISTANT_CONVERSATION_MODEL "anthropic/claude-haiku-4-5"
write_env ASSISTANT_VOICE "Telnyx.Ultra.81d6df1d-6175-4f24-9641-76d14b6d67cc"
