EXTERNAL_URL_VALUE="${RAW_EXTERNAL_URL/postgresql:\/\//postgresql+asyncpg:\/\/}"
EXTERNAL_URL_VALUE="${EXTERNAL_URL_VALUE/postgres:\/\//postgresql+asyncpg:\/\/}"
