# ── Stage 10 ───────────────────────────────────────────────────────────────
stage "Verify the deploy"
say "Checking what must be true before anyone scans anything:"
_check() { # label url expect_code
  local label="$1" url="$2" expect="$3" code
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 90 "$url" || echo "000")
  if [[ "$code" == "$expect" ]]; then
    printf '  %s✓%s %s (%s)\n' "$GREEN" "$RESET" "$label" "$code"
  else
    printf '  %s✗ %s — got %s, expected %s%s\n' "$RED" "$label" "$code" "$expect" "$RESET"
    SKIPPED+=("verify: $label returned $code (expected $expect)")
  fi
}
note "(a sleeping service takes ~60s on its first hit — that's the free tier)"
